def _90015000checkAction(self, target, context):

    skillLv = self.getSkillLevel(target, context, context.skillId)

    if skillLv < 5:
        buff_level = 15
    elif 5 <= skillLv < 8:
        buff_level = 20
    else:
        buff_level = 25

    selfBuffLv = self.getBuffLv(64001302)

    if selfBuffLv >= buff_level:
        self.showMsg(54479003,[])    
        return False

    if target:
        targetbuffLv = target.getBuffLv(64001302)
        if targetbuffLv >= buff_level:
            self.showMsg(54479003,[])    
            return False 
    return True

def _90015000(self, target, context):
    skillLv = self.getSkillLevel(target, context, context.skillId)

        #铭文效果调用
    buffId = 0
    ret, datas = self.getAvatar().getInscriptionEffects(90010005, 13)
    if ret and datas:
        buffId = int(datas[0])
    if skillLv < 5:
        buff_level = 15
        healnum = 0.075
    elif 5 <= skillLv < 8:
        buff_level = 20
        healnum = 0.1
    elif 8 <= skillLv < 11:
        buff_level = 25
        healnum = 0.125
    else:  # skillLv >= 11
        buff_level = 25
        healnum = 0.125
    # 铭文效果结束

    # 自己
    self.addBuffBySkill(self, context, 64001302, buff_level, 1.0, 10)

    # 召唤物
    for summonId in self.petList:
        summon = KBEngine.entities.get(summonId)
        if not summon:
            continue

        summon.addBuffBySkill(summon, context, 64001302, buff_level, 1.0, 10)
    for eid in context.effectedEntIds:
        e = KBEngine.entities.get(eid)
        if not e:
            continue
        # 排除已拥有 64004520 的单位
        if e.hasBuff(64004520):
            continue

        fullHp = e.getProp("fullHp")       # 改为目标自身血量
        hp = fullHp * healnum

        self.healByNum(e, context, hp, 1, 1)   # 正确治疗
        self.addBuffBySkill(e, context, 64001302, buff_level, 1.0, 5)
        if buffId:
            self.addBuffBySkill(e, context, buffId, 1, 1.0, 5)

    if skillLv >= 11:
        self.castSkill(self, context, 90010007, skillLv)

