    # 根据技能等级映射不同的 Buff ID
    buff_mapping = {
        (0, 5): 64000408,
        (5, 8): 64000409,
        (8, 11): 64000410,
        (11, 12): 64000411,
        (12, float('inf')): 64000412
    }

    # 查找对应的 Buff ID
