def _91017011bystart(self, target, context):

    # 阶段0的执行逻辑
    if context.actionStage == 0:
        self.addBuffBySkill(self, context, 64004909, 1, 1, 10)
        self.addBuffBySkill(self, context, 64004902, 1, 1, -1)

        import sMath
        for tid1 in context.effectedEntIds:
            ent1 = KBEngine.entities.get(tid1)
            if not ent1:
                continue  # 如果实体不存在，跳过
            # 确保攻击者和目标有效
            action_FightAction.stun(self, ent1, context, 2, 0, 0, 1)  

            # 对每个目标单独计算距离
            distance = sMath.distance2D(self.position, ent1.position)
            if distance < 16:
                pushDis = int(17 - distance)
                # 确保拖拽距离不小于0
                pushDis = max(pushDis, 1)
                # 对当前目标执行推击
                action_FightAction.pushTarget(self, ent1, context, pushDis, 12)
                
        return self.callAfterDelay(target, context, 3)
    
    # 阶段1的执行逻辑    
    if context.actionStage == 1:
        summonLv = self.level
        dirOffset1 = 60
        dirOffset2 = 180
        dirOffset3 = 300
        self.summon(self, context, 11237002, 4, 12, summonLv, 1, 1, 0, 8, 180, dirOffset=dirOffset1)
        self.summon(self, context, 11237004, 4, 12, summonLv, 1, 1, 0, 8, 180, dirOffset=dirOffset2)
        self.summon(self, context, 11237003, 4, 12, summonLv, 1, 1, 0, 8, 180, dirOffset=dirOffset3)
        return self.callAfterDelay(target, context, 3.8)

    if context.actionStage == 2:
        self.removeBuff(self, context, 64004909)

