def _91034013(self, target, context):
    import random

    # =========================
    # 30%概率触发
    # 生成3个创生物
    # 70%概率不触发
    # =========================

    if random.random() > 0.3:
        return

    usedAngles = []

    for i in range(3):

        # 防止生成位置太近
        while True:

            angle = random.uniform(0, 360)

            valid = True

            for a in usedAngles:

                diff = abs(angle - a)
                diff = min(diff, 360 - diff)

                # 至少间隔60°
                if diff < 60:
                    valid = False
                    break

            if valid:
                usedAngles.append(angle)
                break

        # 半径35~40
        radius = random.uniform(35, 40)

        # 生成创生物
        self.createCreation(
            target,
            context,

            66000135,      # 创生物ID
            self.level,
            1,

            0,             # ttl
            0,             # cnt

            angle,         # dirOffset
            radius         # posOffset
        )

